C=np.zeros((len(V),11),dtype=np.int64)
for i,x in enumerate(V):
    for j,z in enumerate(x):C[i,z]=(-1)**j
assert all(np.abs(C[a]+C[b]).sum()<=2 for a,b in F.edges())
assert all(np.abs(C[a]+C[b]).sum()<=6 for a,b in W.edges())
assert traces(F)==(0,0)
